import{_ as i,a0 as o,w as d,s as p,I as t,x as r,a1 as a,A as s,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在树莓派 2B 上安装 FreeBSD | LCTT x X-CMD","titleTemplate":false,"description":"如何在树莓派 2B 上安装 FreeBSD | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在树莓派 2B 上安装 FreeBSD | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在树莓派 2B 上安装 FreeBSD | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151030 How To Install FreeBSD on Raspberry Pi 2 Model B","title":"如何在树莓派 2B 上安装 FreeBSD","tag":"201512","desc":""},"relativePath":"201512/20151030 How To Install FreeBSD on Raspberry Pi 2 Model B.md","filePath":"[post].md"}'),u={name:"201512/20151030 How To Install FreeBSD on Raspberry Pi 2 Model B.md"};function b(S,e,f,B,m,D){const n=o("Link");return d(),p("div",null,[e[16]||(e[16]=t("h1",{id:"如何在树莓派-2b-上安装-freebsd",tabindex:"-1"},[r("如何在树莓派 2B 上安装 FreeBSD "),t("a",{class:"header-anchor",href:"#如何在树莓派-2b-上安装-freebsd","aria-label":"Permalink to “如何在树莓派 2B 上安装 FreeBSD”"},"​")],-1)),e[17]||(e[17]=t("p",null,"在树莓派 2B 上如何安装 FreeBSD 10 或 FreeBSD 11（current）？怎么在 Linux，OS X，FreeBSD 或类 Unix 操作系统上烧录 SD 卡？",-1)),e[18]||(e[18]=t("p",null,"在树莓派 2B 上安装 FreeBSD 10 或 FreeBSD 11（current）很容易。使用 FreeBSD 操作系统可以打造一个非常易用的 Unix 服务器。FreeBSD-CURRENT 自2012年十一月以来一直支持树莓派，2015年三月份后也开始支持树莓派2了。在这个快速教程中我将介绍如何在树莓派 2B 上安装 FreeBSD 11 current arm 版。",-1)),e[19]||(e[19]=t("h3",{id:"_1-下载-freebsd-current-的-arm-镜像",tabindex:"-1"},[r("1. 下载 FreeBSD-current 的 arm 镜像 "),t("a",{class:"header-anchor",href:"#_1-下载-freebsd-current-的-arm-镜像","aria-label":"Permalink to “1. 下载 FreeBSD-current 的 arm 镜像”"},"​")],-1)),t("p",null,[e[1]||(e[1]=r("你可以 ",-1)),a(n,{href:"ftp://ftp.freebsd.org/pub/FreeBSD/snapshots/arm/armv6/ISO-IMAGES/11.0"},{default:s(()=>[...e[0]||(e[0]=[r("访问这个页面来下载",-1)])]),_:1}),e[2]||(e[2]=r(" 树莓派2的镜像。使用 wget 或 curl 命令来下载镜像：",-1))]),e[20]||(e[20]=l(`<pre><code>$ wget ftp://ftp.freebsd.org/pub/FreeBSD/snapshots/arm/armv6/ISO-IMAGES/11.0/FreeBSD-11.0-CURRENT-arm-armv6-RPI2-20151016-r289420.img.xz
</code></pre><p>或</p><pre><code>$ curl -O ftp://ftp.freebsd.org/pub/FreeBSD/snapshots/arm/armv6/ISO-IMAGES/11.0/FreeBSD-11.0-CURRENT-arm-armv6-RPI2-20151016-r289420.img.xz
</code></pre><h3 id="_2-解压-freebsd-current-镜像" tabindex="-1">2. 解压 FreeBSD-current 镜像 <a class="header-anchor" href="#_2-解压-freebsd-current-镜像" aria-label="Permalink to “2. 解压 FreeBSD-current 镜像”">​</a></h3><p>执行以下命令中的任何一个：</p><pre><code>$ unxz FreeBSD-11.0-CURRENT-arm-armv6-RPI2-20151016-r289420.img.xz
</code></pre><p>或</p><pre><code>$ xz --decompress FreeBSD-11.0-CURRENT-arm-armv6-RPI2-20151016-r289420.img.xz
</code></pre><h3 id="_3-设置-sd" tabindex="-1">3. 设置 SD <a class="header-anchor" href="#_3-设置-sd" aria-label="Permalink to “3. 设置 SD”">​</a></h3><p>你可以在 OS X，Linux，FreeBSD，MS-Windows 和类 Unix 系统来烧录 SD 卡。</p><h3 id="在-mac-os-x-下烧录-freebsd-current" tabindex="-1">在 Mac OS X 下烧录 FreeBSD-current <a class="header-anchor" href="#在-mac-os-x-下烧录-freebsd-current" aria-label="Permalink to “在 Mac OS X 下烧录 FreeBSD-current”">​</a></h3><p>使用下面的 dd 命令：</p><pre><code>$ diskutil list
$ diskutil unmountDisk /dev/diskN
$ sudo dd if=FreeBSD-11.0-CURRENT-arm-armv6-RPI2-20151016-r289420.img of=/dev/disk2 bs=64k
</code></pre><p>示例输出:</p><pre><code>1024+0 records in
1024+0 records out
1073741824 bytes transferred in 661.669584 secs (1622776 bytes/sec)
</code></pre><h4 id="使用-linux-freebsd-或者类-unix-系统来烧录-freebsd-current" tabindex="-1">使用 Linux/FreeBSD 或者类 Unix 系统来烧录 FreeBSD-current <a class="header-anchor" href="#使用-linux-freebsd-或者类-unix-系统来烧录-freebsd-current" aria-label="Permalink to “使用 Linux/FreeBSD 或者类 Unix 系统来烧录 FreeBSD-current”">​</a></h4><p>语法是这样:</p><pre><code>$ dd if=FreeBSD-11.0-CURRENT-arm-armv6-RPI2-20151016-r289420.img of=/dev/sdb bs=1M
</code></pre><p><strong>确保使用实际的 SD 卡的设备名称来替换 /dev/sdb</strong>（LCTT 译注：千万注意不要写错了）。</p><h3 id="_4-引导-freebsd" tabindex="-1">4. 引导 FreeBSD <a class="header-anchor" href="#_4-引导-freebsd" aria-label="Permalink to “4. 引导 FreeBSD”">​</a></h3><p>在树莓派 2B 上插入 SD 卡。你需要连接键盘，鼠标和显示器。我使用的是 USB 转串口线来连接显示器的：</p><p><img src="http://s0.cyberciti.org/uploads/faq/2015/10/Raspberry-Pi-2-Model-B.pin-out.jpg" alt="Fig.01 RPi USB based serial connection"></p><p><em>图01 基于树莓派 USB 的串行连接</em></p><p>在下面的例子中，我使用 screen 命令来连接我的 RPI：</p><pre><code>## Linux 上 ##
screen /dev/tty.USB0 115200
 
## OS X 上 ##
screen /dev/cu.usbserial 115200
 
## Windows 请使用 Putty.exe ##
</code></pre><p>FreeBSD RPI 启动输出样例：</p><p><img src="http://s0.cyberciti.org/uploads/faq/2015/10/freebsd-current-rpi.gif" alt="Gif 01: Booting FreeBSD-current on RPi 2"></p><p><em>图02: 在树莓派 2上引导 FreeBSD-current</em></p><h3 id="_5-freebsd-在-rpi-2上的用户名和密码" tabindex="-1">5. FreeBSD 在 RPi 2上的用户名和密码 <a class="header-anchor" href="#_5-freebsd-在-rpi-2上的用户名和密码" aria-label="Permalink to “5. FreeBSD 在 RPi 2上的用户名和密码”">​</a></h3><p>默认的密码是 freebsd/freebsd 和 root/root。</p><p>到此为止, FreeBSD-current 已经安装并运行在树莓派 2上。</p><hr>`,32)),t("p",null,[e[4]||(e[4]=r("via: ",-1)),a(n,{href:"http://www.cyberciti.biz/faq/how-to-install-freebsd-on-raspberry-pi-2-model-b/"},{default:s(()=>[...e[3]||(e[3]=[r("http://www.cyberciti.biz/faq/how-to-install-freebsd-on-raspberry-pi-2-model-b/",-1)])]),_:1})]),t("p",null,[e[8]||(e[8]=r("作者：",-1)),a(n,{href:"http://www.cyberciti.biz/tips/about-us"},{default:s(()=>[...e[5]||(e[5]=[r("Vivek Gite",-1)])]),_:1}),e[9]||(e[9]=r(" 译者：",-1)),a(n,{href:"https://github.com/strugglingyouth"},{default:s(()=>[...e[6]||(e[6]=[r("strugglingyouth",-1)])]),_:1}),e[10]||(e[10]=r(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:s(()=>[...e[7]||(e[7]=[r("wxy",-1)])]),_:1})]),t("p",null,[e[13]||(e[13]=r("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[11]||(e[11]=[r("LCTT",-1)])]),_:1}),e[14]||(e[14]=r(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:s(()=>[...e[12]||(e[12]=[r("Linux中国",-1)])]),_:1}),e[15]||(e[15]=r(" 荣誉推出",-1))])])}const g=i(u,[["render",b]]);export{T as __pageData,g as default};
